window.DaliExperience={create(ctx){
 'use strict';
 const {gallery:G,esc,icon,btn,shell,go,save,toast}=ctx,M=window.DALI_MAP;
 const S=()=>ctx.getState();
 let selected='caicun',zoom=1;
 const selfie=()=>G.assets.find(p=>p.id==='xiaowang-05');
 const current=()=>M.places.find(p=>p.id===selected)||M.places[0];
 function camera(){return shell('相机',`<div class="camera-view camera-couple"><img class="camera-selfie" src="${esc(selfie().path)}" alt="和小王在夕阳下的原始合照"><div class="view-grid"></div><div class="camera-frame"></div><div class="camera-flash" id="camera-flash"></div></div><div class="camera-controls"><span>照片</span>${btn('shutter','','shutter','aria-label="拍照"')}</div>`,{className:'camera-app',scrollClass:'camera-layout'});}
 function capture(){return `<h2>已存入最近项目</h2><img class="capture-selfie" src="${esc(selfie().path)}" alt="和小王的合照">${btn('capture-photos','去照片看看','primary-button wide')}`;}
 function captureCard(){return `<h3 class="gallery-section-title">最近项目</h3><div class="gallery-grid"><button class="photo-card" data-action="capture-view"><div class="photo-image"><img class="capture-thumb" src="${esc(selfie().path)}" alt="和小王的合照"></div><p>和小王的合照 · ${S().captures} 张</p></button></div>`;}
 function mapMarkup(){return `<svg class="dali-map-svg" viewBox="0 0 875 1300" role="img" aria-label="大理洱海和周边道路地图"><defs><linearGradient id="dali-land" x2="1"><stop stop-color="#d7e3cc"/><stop offset=".55" stop-color="#edf0e5"/><stop offset="1" stop-color="#e4ebdc"/></linearGradient><pattern id="dali-water" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M0 8h6m4 6h5" fill="none" stroke="#94c5db" stroke-width=".3"/></pattern></defs><rect width="875" height="1300" fill="url(#dali-land)"/><path d="${M.town}" fill="#ece6df" stroke="#d3d0c4" stroke-width="1.4"/><path d="${M.lake}" fill="#b4d9e9" stroke="#9dc9dd" stroke-width="1.5" fill-rule="evenodd"/><path d="${M.lake}" fill="url(#dali-water)" fill-rule="evenodd"/>${M.roads.map(r=>`<g class="dali-road ${r.kind}"><path d="${r.d}" class="road-edge"/><path d="${r.d}" class="road-line"/></g>`).join('')}<g class="dali-map-labels"><text x="438" y="630" class="lake-label" transform="rotate(-18 438 630)">洱 海</text><text x="135" y="795" class="mountain-label" transform="rotate(-32 135 795)">苍 山</text><text x="605" y="1130" class="district-label">大理市</text><text x="295" y="1248" class="district-label">下关</text><text x="320" y="165" class="district-label">上关</text></g>${M.places.map(p=>`<g class="dali-place-marker ${selected===p.id?'selected':''}" data-action="dali-select" data-place="${p.id}" role="button" tabindex="0" aria-label="在地图上选择${esc(p.name)}" transform="translate(${p.point.join(' ')})"><circle class="map-marker-halo" r="24"/><circle class="map-marker-dot" r="7"/><text x="13" y="-13">${esc(p.name)}</text></g>`).join('')}</svg>`;}
 function viewBox(){const p=current();if(zoom===1)return '0 0 875 1300';const h=1300/zoom,w=875/zoom;return `${Math.max(0,Math.min(875-w,p.point[0]-w/2))} ${Math.max(0,Math.min(1300-h,p.point[1]-h/2))} ${w} ${h}`;}
 function updateMap(){document.querySelector('.dali-map-svg')?.setAttribute('viewBox',viewBox());const place=current();document.querySelectorAll('.dali-place-marker').forEach(el=>el.classList.toggle('selected',el.dataset.place===selected));document.querySelectorAll('[data-action="dali-select"]:not(.dali-place-marker)').forEach(el=>el.classList.toggle('active',el.dataset.place===selected));const title=document.getElementById('dali-place-title'),detail=document.getElementById('dali-place-detail');if(title)title.textContent=place.name;if(detail)detail.textContent=place.tag+' · '+place.detail;const favorite=document.querySelector('[data-action="dali-save"]');if(favorite){const saved=(S().mapSavedPlaces||[]).includes(place.id);favorite.textContent=saved?'已收藏':'收藏';favorite.setAttribute('aria-pressed',String(saved));}document.getElementById('dali-scale').textContent=zoom===1?'大理 · 洱海':zoom===2?'周边街道':'附近道路';}
 function maps(){return shell('地图',`<div class="dali-map-canvas">${mapMarkup()}<div class="dali-map-heading"><span>${icon('compass')} 云南 · 大理</span><b id="dali-scale">大理 · 洱海</b></div><div class="dali-map-controls">${btn('dali-north','N','','aria-label="回到大理全景"')}${btn('dali-zoom','+','','data-delta="1" aria-label="放大地图"')}${btn('dali-zoom','−','','data-delta="-1" aria-label="缩小地图"')}</div><a class="dali-attribution" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a></div><section class="dali-place-sheet"><div class="dali-sheet-grab"></div><label class="dali-place-search">${icon('search')}<input id="dali-search" aria-label="搜索大理地点" type="search" placeholder="搜索大理地点"></label><div class="dali-place-options">${M.places.map(p=>btn('dali-select',esc(p.name),p.id===selected?'active':'',`data-place="${p.id}"`)).join('')}</div><div class="dali-place-description"><div><h2 id="dali-place-title">${esc(current().name)}</h2><p id="dali-place-detail">${esc(current().tag+' · '+current().detail)}</p></div>${btn('dali-save',(S().mapSavedPlaces||[]).includes(selected)?'已收藏':'收藏','','aria-pressed="'+(S().mapSavedPlaces||[]).includes(selected)+'"')}</div>${btn('dali-photos',icon('grid')+' 和小王的照片','dali-photos-link')}</section>`,{className:'maps-app',scrollClass:'dali-map-layout'});}
 const checklist=['带一件外套','带上相机','牵好小王的手'];
 function note(){const checked=S().noteChecks||[],complete=checklist.every((_,i)=>checked.includes(i));return `<div class="sweet-note"><p class="sweet-note-date">大理 · 下次出门</p><p class="sweet-note-intro">别光顾着拍照，出门前看看有没有落下什么。</p><div class="sweet-checklist">${checklist.map((text,i)=>btn('dali-note-check',`<span class="sweet-check">${checked.includes(i)?icon('check'):''}</span><span>${text}</span>`,checked.includes(i)?'done':'',`data-index="${i}" aria-pressed="${checked.includes(i)}"`)).join('')}</div>${complete?`<div class="sweet-note-reveal"><span>♡</span><p>东西落下了还能回去拿，<br>手牵上了就不许松。</p><small>—— 小王</small>${btn('dali-photos','把我们的合照收好 '+icon('chevron'))}</div>`:`<p class="sweet-note-hint">${checked.length?'还有一样，最重要。':'最后一样，不许忘。'}</p>`}</div>`;}
 function action(a,t){if(a==='dali-select'){selected=t.dataset.place;zoom=2;updateMap();return true;}if(a==='dali-zoom'){zoom=Math.max(1,Math.min(3,zoom+Number(t.dataset.delta)));updateMap();return true;}if(a==='dali-north'){zoom=1;updateMap();return true;}if(a==='dali-save'){S().mapSavedPlaces||=[];const i=S().mapSavedPlaces.indexOf(selected);if(i<0)S().mapSavedPlaces.push(selected);else S().mapSavedPlaces.splice(i,1);save();updateMap();return true;}if(a==='dali-photos'){go('album',{id:'xiaowang'});return true;}if(a==='dali-note-check'){S().noteChecks||=[];const index=Number(t.dataset.index),i=S().noteChecks.indexOf(index);if(i<0)S().noteChecks.push(index);else S().noteChecks.splice(i,1);if(checklist.every((_,n)=>S().noteChecks.includes(n))&&!S().discovered.includes('dali-hand'))S().discovered.push('dali-hand');save();document.getElementById('dali-note-content').innerHTML=note();return true;}return false;}
 function input(el){if(el.id!=='dali-search')return false;document.querySelectorAll('.dali-place-options button').forEach(b=>b.hidden=!b.textContent.includes(el.value.trim()));return true;}
 return {camera,capture,captureCard,maps,note,action,input,afterRender(){if(ctx.getRoute().app==='maps')updateMap();}};
}};
